package com.daniil.wristlens.core;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;

public class CaptureEventsTest {
 @Test public void duplicateHeartbeatsAndOldPacketsDoNotReplayShutter(){CaptureEvents log=new CaptureEvents();CaptureEvents.Cursor c=new CaptureEvents.Cursor();assertNull(c.accept("session",0,log.snapshot()));log.add(100,CaptureEvents.Kind.PHOTO);var old=log.snapshot();assertEquals(CaptureEvents.Kind.PHOTO,c.accept("session",100,old).kind());assertNull(c.accept("session",200,old));log.add(300,CaptureEvents.Kind.START);assertEquals(CaptureEvents.Kind.START,c.accept("session",300,log.snapshot()).kind());assertNull(c.accept("session",100,old));}
 @Test public void eachOfFiftyBurstFramesIsDeliveredOnceAt200ms(){CaptureEvents log=new CaptureEvents();CaptureEvents.Cursor c=new CaptureEvents.Cursor();c.accept("s",0,List.of());HoldBurst hold=new HoldBurst();hold.start("hold",0,50);for(int i=1;i<=50;i++){long time=i*200L;hold.renew("hold",time);assertTrue(hold.take(time));log.add(time,CaptureEvents.Kind.BURST_PHOTO);assertEquals(CaptureEvents.Kind.BURST_PHOTO,c.accept("s",time,log.snapshot()).kind());assertNull(c.accept("s",time,log.snapshot()));}assertFalse(hold.take(10_001));assertEquals(32,log.snapshot().size());}
 @Test public void resumeAndNewSessionSkipExistingHistory(){CaptureEvents log=new CaptureEvents();log.add(100,CaptureEvents.Kind.PHOTO);CaptureEvents.Cursor c=new CaptureEvents.Cursor();assertNull(c.accept("a",100,log.snapshot()));log.add(200,CaptureEvents.Kind.STOP);assertNotNull(c.accept("a",200,log.snapshot()));c.reset();assertNull(c.accept("a",200,log.snapshot()));assertNull(c.accept("b",200,log.snapshot()));}
 @Test public void backlogDoesNotPlaySeveralSoundsAtOnceAndOldEventsExpire(){CaptureEvents log=new CaptureEvents();CaptureEvents.Cursor c=new CaptureEvents.Cursor();c.accept("s",0,List.of());for(int i=1;i<=8;i++)log.add(i*200,CaptureEvents.Kind.BURST_PHOTO);assertEquals(8,c.accept("s",1600,log.snapshot()).id());log.add(1700,CaptureEvents.Kind.PAUSE);assertNull(c.accept("s",4000,log.snapshot()));assertNull(c.accept("s",4100,log.snapshot()));}
 @Test public void allVideoTransitionsHaveDistinctEvents(){CaptureEvents log=new CaptureEvents();CaptureEvents.Cursor c=new CaptureEvents.Cursor();c.accept("s",0,List.of());int time=0;for(var kind:List.of(CaptureEvents.Kind.START,CaptureEvents.Kind.PAUSE,CaptureEvents.Kind.RESUME,CaptureEvents.Kind.STOP)){time+=100;log.add(time,kind);assertEquals(kind,c.accept("s",time,log.snapshot()).kind());}}
 @Test public void burstDefaultIs200AndOlderSlowerChoicesRemain(){assertEquals(200,BurstSettings.DEFAULT_INTERVAL_MS);assertArrayEquals(new int[]{200,250,500,1000,2000,5000},BurstSettings.INTERVALS);assertEquals(200,BurstSettings.interval(1));assertEquals(5000,BurstSettings.interval(9000));assertEquals(250,BurstSettings.interval(250));}
}
